sys_script_include.script:
var EventVenueUtils = Class.create();
EventVenueUtils.prototype = {
    initialize: function() {},

    getVenueDetails: function(eventId) {
        if (!eventId) {
            return { error: "Event ID is required." };
        }

        var venueGR = new GlideRecord('x_1610434_event_0_venue'); 
        venueGR.addQuery('event_id', eventId);
        venueGR.query();

        if (venueGR.next()) {
            return {
                event_id: venueGR.getValue('event_id'),
                venue_name: venueGR.getValue('venue_name'),
                location: venueGR.getValue('location'),
                capacity: venueGR.getValue('capacity'),
                contact_person: venueGR.getValue('contact_person'),
                contact_number: venueGR.getValue('contact_number')
            };
        }

        return { error: "No venue details found for the specified event." };
    },

    type: 'EventVenueUtils'
};
